Runs 4 minimal requests against the configured DeepSeek endpoint and prints
ONLY statuses / error codes. The API key is read from the project settings and
never printed.

Matrix (each variant replays the SAME round-1 answer):
  A  round 1: request with `tools` -> capture reasoning_content + tool_calls
  B  round 2: assistant(tool_calls, content=<text>) WITHOUT reasoning_content
  C  round 2: assistant(tool_calls, content=<text>) WITH reasoning_content
  D  round 2: assistant(tool_calls, content=null)  WITHOUT reasoning_content
"""

import glob
import json
import os

from openai import OpenAI

SETTINGS_DIR = "/home/codx-junior/.codx-junior/settings"


def _iter_json(path):
    try:
        with open(path, "r", encoding="utf-8") as fh:
            return json.load(fh)
    except Exception:
        return None


def find_deepseek_credentials():
    """Locate api_url/api_key/model for DeepSeek in the project settings."""
    provider_url = None
    api_key = None
    model = None

    for path in glob.glob(os.path.join(SETTINGS_DIR, "*.json")):
        data = _iter_json(path)
        if data is None:
            continue
        blob = json.dumps(data)

        def walk(node):
            nonlocal provider_url, api_key, model
            if isinstance(node, dict):
                values = {k: v for k, v in node.items() if isinstance(v, str)}
                url = next(
                    (v for v in values.values() if "api.deepseek.com" in v), None
                )
                if url:
                    provider_url = url
                    key = values.get("api_key") or ""
                    if key.startswith("sk-"):
                        api_key = key
                    name = values.get("model") or ""
                    if name.startswith("deepseek"):
                        model = name
                for value in node.values():
                    walk(value)
            elif isinstance(node, list):
                for value in node:
                    walk(value)

        walk(blob and data)

    if not api_key:
        api_key = os.environ.get("DEEPSEEK_API_KEY") or ""
    return provider_url or "https://api.deepseek.com/v1", api_key, model or "deepseek-flash"


TOOLS = [
    {
        "type": "function",
        "function": {
            "name": "get_date",
            "description": "Get the current date.",
            "parameters": {"type": "object", "properties": {}},
        },
    }
]


def call(client, model, messages, label, tools=TOOLS, stream=True):
    """Run one completion and report the outcome without leaking content."""
    try:
        if not stream:
            resp = client.chat.completions.create(
                model=model,
                messages=messages,
                tools=tools,
                max_tokens=128,
                reasoning_effort="low",
            )
            msg = resp.choices[0].message
            return (
                "OK",
                getattr(msg, "reasoning_content", None) or "",
                getattr(msg, "tool_calls", None) or [],
                getattr(msg, "content", None),
            )

        reasoning_parts, content_parts, tool_calls = [], [], []
        stream_resp = client.chat.completions.create(
            model=model,
            messages=messages,
            tools=tools,
            max_tokens=128,
            reasoning_effort="low",
            stream=True,
        )
        for chunk in stream_resp:
            if not chunk.choices:
                continue
            delta = chunk.choices[0].delta
            rc = getattr(delta, "reasoning_content", None)
            if rc:
                reasoning_parts.append(rc)
            if delta.content:
                content_parts.append(delta.content)
            if getattr(delta, "tool_calls", None):
                tool_calls.extend(delta.tool_calls)
        return "OK", "".join(reasoning_parts), tool_calls, "".join(content_parts)
    except Exception as ex:  # noqa: BLE001 - probe wants the provider error
        status = getattr(ex, "status_code", None)
        return f"FAIL({type(ex).__name__}, status={status})", str(ex)[:180], [], None


def main():
    api_url, api_key, model = find_deepseek_credentials()
    print(f"endpoint={api_url} model={model} key_present={bool(api_key)}")
    if not api_key:
        print("NO KEY FOUND - aborting")
        return

    client = OpenAI(api_key=api_key, base_url=api_url)
    user_msg = {"role": "user", "content": "Call get_date. Do not answer in words."}

    status, reasoning, tool_calls, content = call(
        client, model, [user_msg], "round1"
    )
    print(f"A round1 -> {status}")
    if status != "OK":
        print(f"   detail: {reasoning}")
        return

    print(f"   reasoning_chars={len(reasoning)} content={content!r} "
          f"tool_calls={len(tool_calls)}")
    if not tool_calls:
        print("   no tool call returned - cannot continue the matrix")
        return

    call_id = getattr(tool_calls[0], "id", None) or "call_1"
    fn_name = getattr(getattr(tool_calls[0], "function", None), "name", "get_date")
    fn_args = getattr(getattr(tool_calls[0], "function", None), "arguments", "{}")

    tool_result = {"role": "tool", "tool_call_id": call_id, "content": "2026-01-01"}

    def assistant(content_value, with_reasoning):
        msg = {
            "role": "assistant",
            "content": content_value,
            "tool_calls": [
                {
                    "id": call_id,
                    "type": "function",
                    "function": {"name": fn_name, "arguments": fn_args or "{}"},
                }
            ],
        }
        if with_reasoning:
            msg["reasoning_content"] = reasoning
        return msg

    # B: exactly what SmolAgent sends today (content=<text>, no reasoning)
    status_b, err_b, _, _ = call(
        client,
        model,
        [user_msg, assistant(content or None, False), tool_result],
        "no-reasoning",
    )
    print(f"B no reasoning_content          -> {status_b} {err_b[:120] if status_b != 'OK' else ''}")

    # C: with reasoning_content echoed back
    status_c, err_c, _, _ = call(
        client,
        model,
        [user_msg, assistant(content or None, True), tool_result],
        "with-reasoning",
    )
    print(f"C with reasoning_content        -> {status_c} {err_c[:120] if status_c != 'OK' else ''}")

    # D: non-streaming variant, content=null, no reasoning
    status_d, err_d, _, _ = call(
        client,
        model,
        [user_msg, assistant(None, False), tool_result],
        "no-reasoning-null",
        stream=False,
    )
    print(f"D no reasoning (content=null)   -> {status_d} {err_d[:120] if status_d != 'OK' else ''}")

    # E: non-streaming variant WITH reasoning
    status_e, err_e, _, _ = call(
        client,
        model,
        [user_msg, assistant(None, True), tool_result],
        "with-reasoning-null",
        stream=False,
    )
    print(f"E with reasoning (content=null) -> {status_e} {err_e[:120] if status_e != 'OK' else ''}")


if __name__ == "__main__":
