    sig = []
    for m in messages:
        role = m.get("role")
        if role == "assistant":
            flags = []
            if m.get("tool_calls"):
                flags.append(f"tc{len(m['tool_calls'])}")
            if m.get("reasoning_content"):
                flags.append(f"rc{len(m['reasoning_content'])}")
            if m.get("content") in (None, ""):
                flags.append("empty")
            sig.append("A(" + ",".join(flags) + ")" if flags else "A")
        elif role == "tool":
            sig.append("T")
        elif role == "user":
            sig.append("U")
        elif role == "system":
            sig.append("S")
        else:
            sig.append(str(role))
