"""End-to-end check with the REAL helpers against the configured provider.

Round 1: stream a completion with tools -> content, tool_calls, reasoning.
Round 2: build the assistant message with
         codx.junior.ai.smol.messages.make_assistant_tool_calls_message (the
         function the agent now uses) and continue the conversation.

Asserts that the real payload produced by the fixed code is accepted and that
the chain of thought survives the round trip.
"""

import glob
import json
import os
import sys

API = "/home/codx-junior-projects/codx-junior/codx-junior-platform/api"
sys.path.insert(0, API)

from openai import OpenAI  # noqa: E402

SETTINGS_DIR = "/home/codx-junior/.codx-junior/settings"


def creds():
    provider_url, api_key, model = None, None, None
    for path in glob.glob(os.path.join(SETTINGS_DIR, "*.json")):
        try:
            with open(path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
        except Exception:
            continue

        def walk(node):
            nonlocal provider_url, api_key, model
            if isinstance(node, dict):
                values = {k: v for k, v in node.items() if isinstance(v, str)}
                url = next((v for v in values.values() if "api.deepseek.com" in v), None)
                if url:
                    provider_url = url
                    key = values.get("api_key") or ""
                    if key.startswith("sk-"):
                        api_key = key
                    name = values.get("model") or ""
                    if name.startswith("deepseek"):
                        model = name
                for value in node.values():
                    walk(value)
            elif isinstance(node, list):
                for value in node:
                    walk(value)

        walk(data)
    return (
        provider_url or "https://api.deepseek.com/v1",
        api_key or os.environ.get("DEEPSEEK_API_KEY") or "",
        model or "deepseek-flash",
    )


TOOLS = [{
    "type": "function",
    "function": {
        "name": "get_date",
        "description": "Get the current date.",
        "parameters": {"type": "object", "properties": {}},
    },
}]


def stream(client, model, messages):
    """Stream one completion, mirroring SmolAgent._stream_completion."""
    reasoning_parts, content_parts = [], []
    calls = {}
    resp = client.chat.completions.create(
        model=model,
        messages=messages,
        tools=TOOLS,
        max_tokens=200,
        stream=True,
        stream_options={"include_usage": True},
    )
    for chunk in resp:
        if not chunk.choices:
            continue
        delta = chunk.choices[0].delta
        rc = getattr(delta, "reasoning_content", None)
        if isinstance(rc, str) and rc:
            reasoning_parts.append(rc)
        if delta.content:
            content_parts.append(delta.content)
        for tc in getattr(delta, "tool_calls", None) or []:
            entry = calls.setdefault(tc.index, {"id": None, "function": "", "arguments": ""})
            if tc.id:
                entry["id"] = tc.id
            if tc.function and tc.function.name:
                entry["function"] += tc.function.name
            if tc.function and tc.function.arguments:
                entry["arguments"] += tc.function.arguments
    return "".join(content_parts), "".join(reasoning_parts), calls


def main():
    api_url, api_key, model = creds()
    if not api_key:
        print("no key")
        return
    client = OpenAI(api_key=api_key, base_url=api_url)

    from codx.junior.ai.smol.messages import make_assistant_tool_calls_message

    messages = [{"role": "user",
                 "content": "Call get_date to get today's date. Do not answer in words."}]
    content, reasoning, calls = stream(client, model, messages)
    print(f"round1: content_chars={len(content)} reasoning_chars={len(reasoning)} "
          f"tool_calls={len(calls)}")
    if not calls:
        print("no tool call -> cannot continue")
        return

    tool_calls = {entry["id"] or f"call_{idx}": {
        "id": entry["id"] or f"call_{idx}",
        "type": "function",
        "function": entry["function"],
        "arguments": entry["arguments"] or "{}",
    } for idx, entry in calls.items()}

    assistant = make_assistant_tool_calls_message(
        tool_calls, content=content, reasoning_content=reasoning
    )
    print(f"assistant message keys={sorted(assistant.keys())} "
          f"echoes_reasoning={'reasoning_content' in assistant}")

    messages.append(assistant)
    for call_id, info in tool_calls.items():
        messages.append({"role": "tool", "tool_call_id": call_id,
                         "content": "2026-01-01"})

    try:
        content2, reasoning2, calls2 = stream(client, model, messages)
        print(f"round2: OK content={content2[:60]!r} "
              f"reasoning_chars={len(reasoning2)} tool_calls={len(calls2)}")
        print("RESULT: the payload built by the fixed code is ACCEPTED")

        # Control: the same continuation WITHOUT the reasoning echo.
        legacy = make_assistant_tool_calls_message(tool_calls, content=content)
        legacy_messages = [messages[0], legacy] + messages[2:]
        print(f"control: legacy message echoes_reasoning="
              f"{'reasoning_content' in legacy}")
        try:
            stream(client, model, legacy_messages)
            print("control: provider tolerated the missing reasoning (as observed)")
        except Exception as ex:  # noqa: BLE001
            print(f"control: provider rejected it -> {str(ex)[:120]}")
    except Exception as ex:  # noqa: BLE001
        print(f"round2 FAILED: {str(ex)[:300]}")


if __name__ == "__main__":
    main()
